import { action, addCommonDatenfelderSearchOptions, choiceOption, commonDatenfelderParams, parseNonEmpty, renderJson, renderRaw, } from "../shared.js";
import { FeldartValues, DatentypValues, FeldSucheInValues } from "@maschinenlesbar.org/fim-portal-client/internal/enums";
export function registerFieldCommands(program, deps) {
    const fields = program.command("fields").description("Datenfelder (data fields)");
    const search = fields
        .command("search")
        .description("Search/filter data fields")
        .addOption(choiceOption("--suche-nur-in <module>", "restrict full-text search to a module", FeldSucheInValues))
        .addOption(choiceOption("--feldart <art>", "filter by Feldart", FeldartValues))
        .addOption(choiceOption("--datentyp <typ>", "filter by Datentyp", DatentypValues));
    addCommonDatenfelderSearchOptions(search).action(action(deps, async ({ client, global, opts }) => {
        const params = {
            ...commonDatenfelderParams(opts),
            suche_nur_in: opts["sucheNurIn"],
            feldart: opts["feldart"],
            datentyp: opts["datentyp"],
        };
        renderJson(deps, global, await client.fields.search(params));
    }));
    fields
        .command("versions")
        .argument("<namespace>", "namespace of the element", parseNonEmpty)
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .description("List all versions of a data field")
        .action(action(deps, async ({ client, global }, [namespace, fimId]) => {
        renderJson(deps, global, await client.fields.versions(namespace, fimId));
    }));
    fields
        .command("get")
        .argument("<namespace>", "namespace of the element", parseNonEmpty)
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Get a single data field (version defaults to 'latest')")
        .action(action(deps, async ({ client, global }, [namespace, fimId, fimVersion]) => {
        renderJson(deps, global, await client.fields.get(namespace, fimId, fimVersion ?? "latest"));
    }));
    fields
        .command("xdf")
        .argument("<namespace>", "namespace of the element", parseNonEmpty)
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Download the XDatenfelder XML for a data field")
        .action(action(deps, async ({ client, global }, [namespace, fimId, fimVersion]) => {
        await renderRaw(deps, global, await client.fields.downloadXdf(namespace, fimId, fimVersion ?? "latest"));
    }));
}
